applyScript:
$ErrorActionPreference = 'Stop'
foreach ($a in Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' }) {
$base = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
$id = '{' + $a.InterfaceGuid.ToString() + '}'
$key = Get-ChildItem $base -ErrorAction SilentlyContinue | Where-Object { (Get-ItemProperty -Path $_.PSPath -Name 'NetCfgInstanceId' -ErrorAction SilentlyContinue).NetCfgInstanceId -eq $id } | Select-Object -First 1
if (-not $key) { throw ('Could not find the registry key for adapter ' + $a.Name) }
$path = $key.PSPath
  New-ItemProperty -Path $path -Name 'PnPCapabilities' -Value 24 -PropertyType DWord -Force | Out-Null
}
exit 0

checkScript:
$ErrorActionPreference = 'Stop'
$adapters = Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' }
if (-not $adapters) { exit 1 }
foreach ($a in $adapters) {
$base = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
$id = '{' + $a.InterfaceGuid.ToString() + '}'
$key = Get-ChildItem $base -ErrorAction SilentlyContinue | Where-Object { (Get-ItemProperty -Path $_.PSPath -Name 'NetCfgInstanceId' -ErrorAction SilentlyContinue).NetCfgInstanceId -eq $id } | Select-Object -First 1
if (-not $key) { throw ('Could not find the registry key for adapter ' + $a.Name) }
$path = $key.PSPath
  $v = Get-ItemProperty -Path $path -Name 'PnPCapabilities' -ErrorAction SilentlyContinue
  if (-not $v -or $v.PnPCapabilities -ne 24) { exit 1 }
}
exit 0

revertScript:
$ErrorActionPreference = 'Stop'
foreach ($a in Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' }) {
$base = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
$id = '{' + $a.InterfaceGuid.ToString() + '}'
$key = Get-ChildItem $base -ErrorAction SilentlyContinue | Where-Object { (Get-ItemProperty -Path $_.PSPath -Name 'NetCfgInstanceId' -ErrorAction SilentlyContinue).NetCfgInstanceId -eq $id } | Select-Object -First 1
if (-not $key) { throw ('Could not find the registry key for adapter ' + $a.Name) }
$path = $key.PSPath
  Remove-ItemProperty -Path $path -Name 'PnPCapabilities' -ErrorAction SilentlyContinue
}
exit 0
